(function(E){ const x = E["mkt-m2"] = E["mkt-m2"] || {units:{}}; x.units["mkt-6"] = {"grammar":{"id":"c-mkt-6-g","level":"B1","course":"marketing","unit":"mkt-6","title":"Questions that start conversations: Who remembers...? Which colour did you...?","titleTr":"Sohbet başlatan sorular: Who remembers...? Which colour did you...?","titleFa":"سؤال‌هایی که گفتگو را شروع می‌کنند: Who remembers...؟ Which colour did you...؟","formsTable":{"headers":{"en":["Question word = subject: no do","Question word = object: do / does / did"],"tr":["Soru kelimesi özne: do yok","Soru kelimesi nesne: do / does / did"],"fa":["کلمه‌ی پرسشی فاعل: بدون do","کلمه‌ی پرسشی مفعول: do / does / did"]},"rows":[["Who remembers this towel?","Who did you buy it for?"],["What happened at the launch?","What did you think of the launch?"],["Which colour sells best?","Which colour do you want?"]]},"wrong":"Which colour you brought home?","right":"Which colour did you bring home?","blank":{"sentence":"Which colour ___ you bring home last summer?","word":"did","distractors":["do","were"]},"wrong2":"Who want a free sample?","right2":"Who wants a free sample?","blank2":{"sentence":"Who ___ the striped one?","word":"wants","distractors":["want","do want"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Question word = subject: no do.","tr":"Soru kelimesi özne: do yok.","fa":"کلمه‌ی پرسشی فاعل: بدون do.","ex":"Who remembers this towel?"},{"en":"Subject who / what takes the -s form in the present.","tr":"Özne olan who / what geniş zamanda -s alır.","fa":"who / what وقتی فاعل‌اند، در زمان حال فعل ‎-s می‌گیرد.","ex":"Who wants a free sample?"},{"en":"Question word = object: do / does / did + base verb.","tr":"Soru kelimesi nesne: do / does / did + yalın fiil.","fa":"کلمه‌ی پرسشی مفعول: do / does / did + فعل ساده.","ex":"Which colour did you bring home?"}],"test":{"en":"Answer the question. Does your answer take the place of the question word as the subject (\"I remember it!\")? Then no do.","tr":"Soruyu cevapla. Cevabın soru kelimesinin yerine özne olarak mı geçiyor (\"I remember it!\")? O zaman do yok.","fa":"به سؤال جواب بده. جوابت به‌عنوان فاعل جای کلمه‌ی پرسشی می‌نشیند («I remember it!»)؟ پس do نمی‌آید."},"contrast":{"en":"Turkish (\"Hangi rengi getirdin?\") and Persian («چه رنگی آوردی؟») never add a helper verb to questions, so learners forget do in object questions: \"Which colour you brought?\"","tr":"Türkçe sorulara hiçbir zaman yardımcı fiil eklemez (\"Hangi rengi getirdin?\"); bu yüzden nesne sorularında do unutulur: \"Which colour you brought?\"","fa":"فارسی هیچ‌وقت به سؤال فعل کمکی اضافه نمی‌کند («چه رنگی آوردی؟»)؛ برای همین در سؤال‌های مفعولی do جا می‌افتد: «Which colour you brought?»"}},"errorWatch":[{"find":["which colour you brought","which colour you bought","which one you bought","which towel you bought","what you bought?","who does remember"],"fix":{"en":"In an object question, add do / does / did: \"Which colour did you bring home?\" In a subject question, no do: \"Who remembers this towel?\"","tr":"Nesne sorusunda do / does / did ekle: \"Which colour did you bring home?\" Özne sorusunda do yok: \"Who remembers this towel?\"","fa":"در سؤال مفعولی do / does / did اضافه کن: «Which colour did you bring home?» در سؤال فاعلی do نمی‌آید: «Who remembers this towel?»"}}]},"b2":{"id":"c-mkt-6-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-6","title":"Answering a doubt: emphatic do, does, did","titleTr":"Bir şüpheye cevap vermek: vurgulu do, does, did","titleFa":"جواب دادن به تردید: do، does، did تأکیدی","formsTable":{"headers":{"en":["The comment","Your answer"],"tr":["Yorum","Cevabın"],"fa":["کامنت","جواب تو"]},"rows":[["\"Do you even ship to Dubai?\"","We do ship to the UAE."],["\"Softer after washing? I doubt it.\"","It does get softer with every wash."],["\"Did you really test that?\"","We did test it: 20 washes in our lab."]]},"wrong":"It does gets softer with every wash.","right":"It does get softer with every wash.","blank":{"sentence":"It ___ get softer with every wash; we tested it.","word":"does","distractors":["is","do"]},"wrong2":"We did tested it in our lab.","right2":"We did test it in our lab.","blank2":{"sentence":"We did ___ it: twenty washes in our lab.","word":"test","distractors":["tested","testing"]},"useIn":{"en":"B2: in your LinkedIn post, or in a reply to a doubtful comment, use emphatic do, does or did once.","tr":"B2: LinkedIn gönderinde ya da şüpheci bir yoruma verdiğin cevapta bir kez vurgulu do, does ya da did kullan.","fa":"B2: در پست لینکدینت، یا در جواب یک کامنت شکاک، یک بار do، does یا did تأکیدی به کار ببر."},"exitItem":{"from":"mkt-6","kind":"blank","prompt":"\"Do you even ship abroad?\" \"Yes, we ___ ship to thirty countries.\"","options":["are","does","do"],"correct":2},"expParts":{"tryFrom":"blank","rule":[{"en":"Answer a doubt: do / does / did + base verb.","tr":"Bir şüpheye cevap: do / does / did + yalın fiil.","fa":"جواب به تردید: do / does / did + فعل ساده.","ex":"We do ship to the UAE."},{"en":"The main verb stays bare: no -s, no -ed.","tr":"Asıl fiil yalın kalır: -s yok, -ed yok.","fa":"فعل اصلی ساده می‌ماند: بدون ‎-s، بدون ‎-ed.","ex":"It does get softer. We did test it."},{"en":"Use it only to confirm or correct a doubt.","tr":"Sadece bir şüpheyi doğrulamak ya da düzeltmek için kullan.","fa":"فقط برای تأیید یا اصلاح یک تردید.","ex":"\"I doubt it.\" \"It does work.\""}],"test":{"en":"Is someone doubting you? Add do / does / did, and take -s or -ed off the main verb.","tr":"Biri senden şüphe mi ediyor? do / does / did ekle ve asıl fiilden -s ya da -ed'i kaldır.","fa":"کسی به حرفت شک دارد؟ do / does / did اضافه کن و ‎-s یا ‎-ed را از فعل اصلی بردار."},"contrast":{"en":"Turkish and Persian add a word for this (\"gerçekten\", «واقعاً») or use the voice. English can put the stress on do.","tr":"Türkçede bunun için bir kelime eklenir (\"gerçekten\", \"sahiden\") ya da ses tonu kullanılır. İngilizce vurguyu do'nun üzerine koyabilir.","fa":"در فارسی برای این کار کلمه‌ای اضافه می‌کنیم («واقعاً»، «حتماً») یا با لحن صدا تأکید می‌کنیم. انگلیسی می‌تواند تأکید را روی do بگذارد."}},"errorWatch":[{"find":["does gets","does makes","does dries","did tested","did sent","did made","do ships"],"fix":{"en":"After emphatic do / does / did, the main verb stays bare: \"It does get softer\", \"We did test it\".","tr":"Vurgulu do / does / did'den sonra asıl fiil yalın kalır: \"It does get softer\", \"We did test it\".","fa":"بعد از do / does / did تأکیدی فعل اصلی ساده می‌ماند: «It does get softer»، «We did test it»."}}]},"vocab":{"id":"c-mkt-6-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-6","goals":["career"],"title":{"en":"Social Media","tr":"Sosyal Medya","fa":"شبکه‌های اجتماعی"},"cards":[{"word":"post","sentence":"She posted the same message on every platform.","gap":"posted","accept":["posted","post"],"meaning":{"en":"To put a message, photo or video online.","tr":"paylaşmak, gönderi yayınlamak","fa":"پست گذاشتن"}},{"word":"caption","sentence":"Keep the caption under two lines.","meaning":{"en":"The short text under a photo or video.","tr":"gönderi açıklaması","fa":"کپشن؛ متن زیر عکس"}},{"word":"comment","sentence":"The post got 400 comments in one evening.","gap":"comments","accept":["comments","comment"],"meaning":{"en":"A short reply that people write under a post.","tr":"yorum","fa":"کامنت؛ نظر"}},{"word":"engagement","sentence":"Engagement is high when people start answering each other.","meaning":{"en":"How much people react to a post: likes, comments, shares.","tr":"etkileşim","fa":"تعامل (انگیجمنت)"}},{"word":"reach","sentence":"The reach was big, but almost nobody clicked.","meaning":{"en":"How many people saw a post.","tr":"erişim","fa":"دسترسی (ریچ)"}},{"word":"hashtag","sentence":"Three hashtags are enough for one post.","gap":"hashtags","accept":["hashtags","hashtag"],"meaning":{"en":"A word with # in front, used to find posts on a topic.","tr":"hashtag (etiket)","fa":"هشتگ"}},{"word":"platform","sentence":"Each platform needs its own version of the message.","meaning":{"en":"A website or app where people share content, such as Instagram or LinkedIn.","tr":"platform","fa":"پلتفرم"}},{"word":"share","sentence":"People share a question they want their friends to answer.","meaning":{"en":"To pass a post on to other people.","tr":"paylaşmak","fa":"به اشتراک گذاشتن"}},{"word":"followers","sentence":"After one week, the brand had 2,000 followers on Instagram.","meaning":{"en":"People who choose to see your posts.","tr":"takipçiler","fa":"دنبال‌کننده‌ها"}},{"word":"schedule","sentence":"Schedule the LinkedIn post for Tuesday morning.","meaning":{"en":"To choose the time when a post goes online.","tr":"zamanlamak, ileri bir saate planlamak","fa":"زمان‌بندی کردن"}}]},"judge":{"id":"c-mkt-6-j","course":"marketing","unit":"mkt-6","type":"judge","title":{"en":"Right post, right reader","tr":"Doğru gönderi, doğru okur","fa":"پست درست، خواننده‌ی درست"},"prompt":"Four posts. The platform and reader are in [brackets].","parts":["Fits the reader","Clear next step","Right length for the platform"],"instruction":{"en":"Tap what each post does well. The post to publish has all three.","tr":"Her gönderinin iyi yaptığı şeylere dokun. Yayımlanacak gönderide üçü de vardır.","fa":"روی کارهای خوبی که هر پست کرده بزن. پستی که منتشر می‌شود هر سه را دارد."},"items":[{"by":"AI tool","answer":"[LinkedIn, hotel buyers] Elevate your guests' experience with luxurious Turkish towels! #luxury #dream","present":["Right length for the platform"],"fix":{"en":"Short enough, but hotel buyers buy on cost and durability, and there is no next step. Lead with a number.","tr":"Yeterince kısa ama otel alıcıları maliyete ve dayanıklılığa bakar, sonraki adım da yok. Bir rakamla başla.","fa":"به‌اندازه‌ی کافی کوتاه است، ولی خریدار هتل به هزینه و دوام نگاه می‌کند و قدم بعدی هم ندارد. با یک عدد شروع کن."}},{"by":"Good model","answer":"[LinkedIn, cafe owners] What does a bad bean cost you? Not the price per kilo: the customers who don't come back. Our roasts are dated. Which date do you need on your next bag?","present":["Fits the reader","Clear next step","Right length for the platform"],"fix":null},{"by":"AI tool","answer":"[Instagram, home baristas] Discover our premium collection of high-quality coffees, crafted with passion and tradition for the modern lifestyle of today's discerning consumer.","present":[],"fix":{"en":"Too long for a caption, no next step, and it could be any brand. Try: \"Who still buys stale coffee? Find today's roast: link in bio.\"","tr":"Bir açıklama için çok uzun, sonraki adım yok ve her marka olabilir. Şunu dene: \"Who still buys stale coffee? Find today's roast: link in bio.\"","fa":"برای کپشن خیلی بلند است، قدم بعدی ندارد و می‌تواند مال هر برندی باشد. این را امتحان کن: «Who still buys stale coffee? Find today's roast: link in bio.»"}},{"by":"Junior writer","answer":"[LinkedIn, retail buyers] New range: towels and bathrobes. Towels with OEKO-TEX labels; bathrobes certified organic (GOTS).","present":["Fits the reader","Right length for the platform"],"fix":{"en":"Good facts for a buyer. Add the next step: \"Message us for samples.\"","tr":"Bir alıcı için iyi bilgiler. Sonraki adımı ekle: \"Message us for samples.\"","fa":"واقعیت‌های خوبی برای خریدار است. قدم بعدی را اضافه کن: «Message us for samples.»"}}]},"writing":{"id":"c-mkt-6-w","title":{"en":"Two posts, two readers","tr":"İki gönderi, iki okur","fa":"دو پست، دو خواننده"},"course":"marketing","unit":"mkt-6","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-3","prompt":{"en":"Write two posts for one message (60-90 words in total) for your own product, or for this coffee roaster: an Instagram caption for home baristas and a LinkedIn post for cafe owners. Facts: every bag shows its roast date; delivery in 7 days; free sample for cafes. Each post needs a first line, one fact and one next step.","tr":"Tek bir mesaj için iki gönderi yaz (toplam 60-90 kelime), kendi ürünün ya da şu kahve kavurucusu için: evde kahve yapanlara Instagram açıklaması ve kafe sahiplerine LinkedIn gönderisi. Bilgiler: her pakette kavrulma tarihi var; 7 günde teslimat; kafelere ücretsiz numune. Her gönderide bir ilk cümle, bir bilgi ve bir sonraki adım olmalı.","fa":"برای یک پیام دو پست بنویس (در مجموع ۶۰ تا ۹۰ کلمه)، برای محصول خودت یا این برشته‌کار قهوه: یک کپشن اینستاگرام برای کسانی که در خانه قهوه درست می‌کنند و یک پست لینکدین برای صاحبان کافه. واقعیت‌ها: روی هر بسته تاریخ برشته‌کاری هست؛ تحویل ۷ روزه؛ نمونه‌ی رایگان برای کافه‌ها. هر پست جمله‌ی اول، یک واقعیت و یک قدم بعدی می‌خواهد."},"model":"Instagram, home baristas:\nWho still drinks coffee with no date on the bag? Every bag of ours shows its roast date, and it reaches you in 7 days. Which roast did you try last? Find today's: link in bio.\n\nLinkedIn, cafe owners:\nWhat do your customers taste first? Freshness. Every bag we send shows its roast date, and we deliver in 7 days. What do you need on your next order? Message us for a free sample.","frame":"Instagram, ___:\nWho ___? ___. Which ___ did you ___? ___: link in bio.\n\nLinkedIn, ___:\nWhat do ___? ___. ___. What do you ___? Message us ___.","words":[{"word":"who"},{"word":"did you"},{"word":"what do"}],"minWords":60,"minSentences":6,"rubric":["Task done: two posts, one message, first line, one fact, next step in each","Organised: first line, value, next step","Language: subject and object questions with the right form","Tone: each post fits its reader and platform; no empty words"],"rubricI18n":{"tr":["Görev: tek mesajla iki gönderi; her birinde ilk cümle, bir bilgi, sonraki adım","Düzen: ilk cümle, değer, sonraki adım","Dil: özne ve nesne soruları doğru biçimde","Üslup: her gönderi okuruna ve platformuna uyuyor; boş kelime yok"],"fa":["کامل بودن کار: دو پست با یک پیام؛ در هر کدام جمله‌ی اول، یک واقعیت، قدم بعدی","نظم: جمله‌ی اول، ارزش، قدم بعدی","زبان: سؤال فاعلی و مفعولی با شکل درست","لحن: هر پست به خواننده و پلتفرمش می‌خورد؛ بدون کلمه‌ی توخالی"]}},"speaking":{"id":"mkt-6","course":"marketing","unit":"mkt-6","topic":{"en":"Why one post doesn't fit all","tr":"Tek gönderi neden her yere uymaz","fa":"چرا یک پست به همه‌جا نمی‌خورد"},"warmup":{"en":"Which first line made you stop scrolling this week? Why?","tr":"Bu hafta hangi ilk cümle kaydırmayı bırakmanı sağladı? Neden?","fa":"این هفته کدام جمله‌ی اول باعث شد دست نگه داری؟ چرا؟"},"questions":[{"en":"A post got 400 comments on Instagram and three likes on LinkedIn. Explain why.","tr":"Bir gönderi Instagram'da 400 yorum, LinkedIn'de üç beğeni aldı. Nedenini anlat.","fa":"یک پست در اینستاگرام ۴۰۰ کامنت و در لینکدین سه لایک گرفته. توضیح بده چرا."},{"en":"Say what each reader cares about.","tr":"Her okurun neyi önemsediğini söyle.","fa":"بگو هر خواننده به چه چیزی اهمیت می‌دهد."},{"en":"Ask a colleague one question that helps you plan the next post.","tr":"Bir sonraki gönderiyi planlamana yardım edecek bir soruyu iş arkadaşına sor.","fa":"از یک همکار سؤالی بپرس که به برنامه‌ریزی پست بعدی کمک کند."}],"followups":[{"en":"Now explain the difference between two readers of your own product.","tr":"Şimdi kendi ürününün iki okuru arasındaki farkı anlat.","fa":"حالا فرق دو خواننده‌ی محصول خودت را توضیح بده."}],"expressions":[{"phrase":"The message is the same, but...","meaning":{"en":"Separates the idea from the wording.","tr":"Fikri ifadeden ayırır.","fa":"فکر را از شکل گفتن جدا می‌کند."}},{"phrase":"What they care about is...","meaning":{"en":"Names the reader's priority.","tr":"Okurun önceliğini söyler.","fa":"اولویت خواننده را می‌گوید."}},{"phrase":"Who do we want to reply?","meaning":{"en":"Plans the next post.","tr":"Sonraki gönderiyi planlar.","fa":"پست بعدی را برنامه‌ریزی می‌کند."}}],"model":"The post worked on Instagram because people there remembered the towel from a holiday. On LinkedIn it got three likes, because hotel buyers never had that holiday. The message is the same, but the reader is different. What they care about is cost per wash and fast delivery. So who do we want to reply, and which number will make them answer?","selfCheck":[{"en":"I explained why the post failed.","tr":"Gönderinin neden tutmadığını anlattım.","fa":"توضیح دادم چرا پست جواب نداد."},{"en":"I named what each reader cares about.","tr":"Her okurun neyi önemsediğini söyledim.","fa":"گفتم هر خواننده به چه اهمیت می‌دهد."},{"en":"I asked one clear question.","tr":"Net bir soru sordum.","fa":"یک سؤال روشن پرسیدم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم در زمانش تمام شد."}]},"exit":{"id":"c-mkt-6-x","course":"marketing","unit":"mkt-6","type":"exit","items":[{"from":"mkt-6","kind":"blank","prompt":"What ___ your readers look for first?","options":["do","are","have"],"correct":0,"point":2},{"from":"mkt-6","kind":"mcq","prompt":"Which is the strongest first line for hotel buyers?","options":["Welcome to our new post!","Our towels are luxurious.","Our towels survive 150 washes. What does yours cost per wash?"],"correct":2,"point":1},{"from":"mkt-6","kind":"mcq","prompt":"What usually stays the same when you adapt a post?","options":["The message","The length","The next step"],"correct":0,"point":1},{"from":"mkt-5","kind":"blank","prompt":"We sell a ___ hotel towel.","options":["600-grams","600-gram","600 grams"],"correct":1},{"from":"mkt-4","kind":"blank","prompt":"The editor suggested ___ the price per wash.","options":["to show","show","showing"],"correct":2},{"from":"mkt-3","kind":"mcq","prompt":"Which brief line can a writer act on?","options":["Make it pop.","Must not: any price or delivery promise.","Something for everyone."],"correct":1}]},"explain":{"id":"c-mkt-6-e","course":"marketing","unit":"mkt-6","type":"explain","level":"B1","title":{"en":"First lines and posts for each platform","tr":"Her platform için ilk cümle ve gönderi","fa":"جمله‌ی اول و پست برای هر پلتفرم"},"objective":{"en":"In this lesson you will learn to write a strong first line and adapt one message for different platforms and audiences.","tr":"Bu derste güçlü bir ilk cümle yazmayı ve tek bir mesajı farklı platformlara ve kitlelere uyarlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک جمله‌ی اول قوی بنویسی و یک پیام را برای پلتفرم‌ها و مخاطب‌های مختلف تنظیم کنی."},"hook":{"en":"People decide in the first line. Copying one post everywhere wastes that line.","tr":"İnsanlar kararını ilk cümlede verir. Tek gönderiyi her yere kopyalamak o cümleyi boşa harcar.","fa":"آدم‌ها در جمله‌ی اول تصمیم می‌گیرند. کپی کردن یک پست در همه‌جا آن جمله را هدر می‌دهد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"First line, value, next step","tr":"İlk cümle, değer, sonraki adım","fa":"جمله‌ی اول، ارزش، قدم بعدی"},"steps":[{"en":"First line: a question, a number or a small surprise for this reader.","tr":"İlk cümle: bu okur için bir soru, bir rakam ya da küçük bir sürpriz.","fa":"جمله‌ی اول: برای همین خواننده یک سؤال، یک عدد یا یک غافلگیری کوچک.","ex":"What does a towel really cost your hotel?"},{"en":"Value: one idea, with one fact she can use.","tr":"Değer: tek fikir ve okurun işine yarayacak tek bilgi.","fa":"ارزش: یک فکر، با یک واقعیت که به کارش بیاید.","ex":"Not the price per piece: the price per wash."},{"en":"Next step: one clear thing to do now.","tr":"Sonraki adım: şimdi yapılacak tek ve net bir şey.","fa":"قدم بعدی: یک کار روشن برای همین حالا.","ex":"Find your colour: link in bio."},{"en":"For each platform, change the first line, length and next step. Keep the message.","tr":"Her platform için ilk cümleyi, uzunluğu ve sonraki adımı değiştir. Mesaj aynı kalsın.","fa":"برای هر پلتفرم جمله‌ی اول، طول و قدم بعدی را عوض کن. پیام را نگه دار.","ex":"Travel creator: same trip; a reel of the view, a newsletter of the costs."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Questions that start conversations: Who remembers...? Which colour did you...?","tr":"Sohbet başlatan sorular: Who remembers...? Which colour did you...?","fa":"سؤال‌هایی که گفتگو را شروع می‌کنند: Who remembers...؟ Which colour did you...؟"},"steps":[{"en":"Question word = subject: no do.","tr":"Soru kelimesi özne: do yok.","fa":"کلمه‌ی پرسشی فاعل: بدون do.","ex":"Who remembers this towel?"},{"en":"Subject who / what takes the -s form in the present.","tr":"Özne olan who / what geniş zamanda -s alır.","fa":"who / what وقتی فاعل‌اند، در زمان حال فعل ‎-s می‌گیرد.","ex":"Who wants a free sample?"},{"en":"Question word = object: do / does / did + base verb.","tr":"Soru kelimesi nesne: do / does / did + yalın fiil.","fa":"کلمه‌ی پرسشی مفعول: do / does / did + فعل ساده.","ex":"Which colour did you bring home?"}],"table":{"headers":{"en":["Question word = subject: no do","Question word = object: do / does / did"],"tr":["Soru kelimesi özne: do yok","Soru kelimesi nesne: do / does / did"],"fa":["کلمه‌ی پرسشی فاعل: بدون do","کلمه‌ی پرسشی مفعول: do / does / did"]},"rows":[["Who remembers this towel?","Who did you buy it for?"],["What happened at the launch?","What did you think of the launch?"],["Which colour sells best?","Which colour do you want?"]]},"tip":{"en":"Turkish (\"Hangi rengi getirdin?\") and Persian («چه رنگی آوردی؟») never add a helper verb to questions, so learners forget do in object questions: \"Which colour you brought?\"","tr":"Türkçe sorulara hiçbir zaman yardımcı fiil eklemez (\"Hangi rengi getirdin?\"); bu yüzden nesne sorularında do unutulur: \"Which colour you brought?\"","fa":"فارسی هیچ‌وقت به سؤال فعل کمکی اضافه نمی‌کند («چه رنگی آوردی؟»)؛ برای همین در سؤال‌های مفعولی do جا می‌افتد: «Which colour you brought?»"}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Why one post doesn't fit all","tr":"Tek gönderi neden her yere uymaz","fa":"چرا یک پست به همه‌جا نمی‌خورد"},"body":{"en":"On LinkedIn, business buyers usually expect facts and a clear reason to reply. On Instagram, people often stop for a feeling, a memory or a picture. These are working habits, not platform rules, so test them on your own audience.","tr":"LinkedIn'de iş alıcıları genellikle bilgi ve cevap vermek için net bir neden bekler. Instagram'da insanlar çoğu zaman bir duygu, anı ya da görsel için durur. Bunlar platform kuralı değil, çalışma alışkanlığıdır; kendi kitlende dene.","fa":"در لینکدین خریداران تجاری معمولاً واقعیت و دلیلی روشن برای جواب دادن می‌خواهند. در اینستاگرام آدم‌ها اغلب برای یک حس، یک خاطره یا یک تصویر مکث می‌کنند. این‌ها عادت‌های کاری‌اند، نه قانون پلتفرم؛ پس روی مخاطب خودت امتحانشان کن."},"phrases":[{"phrase":"The message is the same, but...","meaning":{"en":"Separates the idea from the wording.","tr":"Fikri ifadeden ayırır.","fa":"فکر را از شکل گفتن جدا می‌کند."}},{"phrase":"What they care about is...","meaning":{"en":"Names the reader's priority.","tr":"Okurun önceliğini söyler.","fa":"اولویت خواننده را می‌گوید."}},{"phrase":"Who do we want to reply?","meaning":{"en":"Plans the next post.","tr":"Sonraki gönderiyi planlar.","fa":"پست بعدی را برنامه‌ریزی می‌کند."}},{"phrase":"caption","meaning":{"en":"The short text under a photo or video.","tr":"gönderi açıklaması","fa":"کپشن؛ متن زیر عکس"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Rebuild a post for a new reader","tr":"Gönderiyi yeni okur için yeniden kur","fa":"پست را برای خواننده‌ی تازه از نو بساز"},"item":"Elevate your guests' experience with luxurious Turkish towels! #luxury #dream","answer":"What does a towel really cost your hotel? Ours are tested to 150 washes at 60°C. Which number matters most to your team?","walk":[{"en":"Who is reading? A hotel buyer on LinkedIn, between two meetings.","tr":"Kim okuyor? LinkedIn'de, iki toplantı arasında bir otel alıcısı.","fa":"چه کسی می‌خواند؟ یک خریدار هتل در لینکدین، بین دو جلسه."},{"en":"Write a first line about the reader's problem, not your towel.","tr":"İlk cümleyi havlun hakkında değil, okurun sorunu hakkında yaz.","fa":"جمله‌ی اول را درباره‌ی مشکل خواننده بنویس، نه حوله‌ی خودت."},{"en":"Add one number, then one easy way to reply.","tr":"Bir rakam ekle, sonra kolay bir cevap yolu.","fa":"یک عدد اضافه کن، بعد یک راه ساده برای جواب دادن."}]},"quick":{"prompt":"When you move a post to a new platform, you keep the ___.","options":["message","first line","hashtags"],"correct":0,"why":{"en":"message: the idea stays. The first line, the length and the next step change for each reader.","tr":"message: fikir kalır. İlk cümle, uzunluk ve sonraki adım her okur için değişir.","fa":"message: فکر می‌ماند. جمله‌ی اول، طول و قدم بعدی برای هر خواننده عوض می‌شود."}},"remember":{"en":"Read only your first line. Would this reader stop for it?","tr":"Sadece ilk cümleni oku. Bu okur onun için durur muydu?","fa":"فقط جمله‌ی اولت را بخوان. این خواننده به خاطرش مکث می‌کند؟"},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Answering a doubt: emphatic do, does, did","tr":"Bir şüpheye cevap vermek: vurgulu do, does, did","fa":"جواب دادن به تردید: do، does، did تأکیدی"},"steps":[{"en":"Answer a doubt: do / does / did + base verb.","tr":"Bir şüpheye cevap: do / does / did + yalın fiil.","fa":"جواب به تردید: do / does / did + فعل ساده.","ex":"We do ship to the UAE."},{"en":"The main verb stays bare: no -s, no -ed.","tr":"Asıl fiil yalın kalır: -s yok, -ed yok.","fa":"فعل اصلی ساده می‌ماند: بدون ‎-s، بدون ‎-ed.","ex":"It does get softer. We did test it."},{"en":"Use it only to confirm or correct a doubt.","tr":"Sadece bir şüpheyi doğrulamak ya da düzeltmek için kullan.","fa":"فقط برای تأیید یا اصلاح یک تردید.","ex":"\"I doubt it.\" \"It does work.\""}],"table":{"headers":{"en":["The comment","Your answer"],"tr":["Yorum","Cevabın"],"fa":["کامنت","جواب تو"]},"rows":[["\"Do you even ship to Dubai?\"","We do ship to the UAE."],["\"Softer after washing? I doubt it.\"","It does get softer with every wash."],["\"Did you really test that?\"","We did test it: 20 washes in our lab."]]},"body":{"en":"B2: in your LinkedIn post, or in a reply to a doubtful comment, use emphatic do, does or did once.","tr":"B2: LinkedIn gönderinde ya da şüpheci bir yoruma verdiğin cevapta bir kez vurgulu do, does ya da did kullan.","fa":"B2: در پست لینکدینت، یا در جواب یک کامنت شکاک، یک بار do، does یا did تأکیدی به کار ببر."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
